loginCheckJs:
var src = result.body();
if (src.match(/Just a moment|Checking your browser|Performing security verification|Verifying you are human/)) {
    cookie.removeCookie(source.bookSourceUrl);
    var url = result.url();
    java.startBrowserAwait(url, "Cloudflare验证");
    result = java.connect(url);
}
result;

