class.site-reader__image@data-page-image-url@js:
list = result.split("\n");
var ref = JSON.stringify({headers: {Referer: "https://dogemanga.com/"}});
var html = "";
for (var i = 0; i < list.length; i++) {
    var u = list[i].trim();
    if (u) {
        html += '<img src="' + u + ',' + ref + '">\n';
    }
}
html;
